CREATE TABLE IF NOT EXISTS domain_pricing (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,tld VARCHAR(32) NOT NULL,registration_price DECIMAL(12,2) NOT NULL DEFAULT 0,renewal_price DECIMAL(12,2) NOT NULL DEFAULT 0,transfer_price DECIMAL(12,2) NOT NULL DEFAULT 0,currency CHAR(3) NOT NULL DEFAULT 'BDT',description VARCHAR(255) DEFAULT NULL,active TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_domain_tld(tld),KEY idx_domain_active_sort(active,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,category VARCHAR(40) NOT NULL,slug VARCHAR(120) NOT NULL,name VARCHAR(160) NOT NULL,short_description VARCHAR(255) DEFAULT NULL,monthly_price DECIMAL(12,2) NOT NULL DEFAULT 0,yearly_price DECIMAL(12,2) DEFAULT NULL,currency CHAR(3) NOT NULL DEFAULT 'USD',features_json JSON DEFAULT NULL,badge VARCHAR(80) DEFAULT NULL,active TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_product_slug(slug),KEY idx_product_category_active(category,active,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE name=VALUES(name),short_description=VALUES(short_description),monthly_price=VALUES(monthly_price),yearly_price=VALUES(yearly_price),currency=VALUES(currency),features_json=VALUES(features_json),badge=VALUES(badge),sort_order=VALUES(sort_order);
